// Approved Mnemba Tips logo (brand/mnemba-tips-logo-master.png). Derivatives are generated by
// scripts/brand/build-logo-assets.mjs; the artwork itself is never redrawn or recoloured.
// The navy wordmark needs a light surface: on navy/dark surfaces wrap it in `.mt-brand-plate`.
const BASE = '/brand/mnemba-tips-wordmark';
const WIDTHS = [240, 480, 960] as const;
const set = (ext: string) => WIDTHS.map(w => `${BASE}-${w}.${ext} ${w}w`).join(', ');

export default function BrandLogo({sizes, priority = false, className = 'mt-brand-logo'}: {sizes: string; priority?: boolean; className?: string}) {
  return <picture>
    <source type="image/avif" srcSet={set('avif')} sizes={sizes}/>
    <source type="image/webp" srcSet={set('webp')} sizes={sizes}/>
    {/* Intrinsic 480×134 keeps the 3.58:1 aspect ratio reserved before load (no layout shift). */}
    <img className={className} src={`${BASE}-480.png`} srcSet={set('png')} sizes={sizes} width={480} height={134}
      alt="Mnemba Tips" decoding="async" loading={priority ? 'eager' : 'lazy'} fetchPriority={priority ? 'high' : 'auto'}/>
  </picture>;
}
